const { UnauthorizedError, NotFoundError } = require("../helper/customErrors");
const { appendFollowers } = require("../helper/helpers");
const {
  User,
  Follower,
  mongoose,
} = require("../models");

//? Profile
const getProfile = async (req, res, next) => {
  try {
    const { loggedUser } = req;
    const { username } = req.params;

    const profile = await User.findOne({ username })
      .select("-email -password")
      .lean();

    if (!profile) throw new NotFoundError("User profile");

    await appendFollowers(loggedUser, profile);

    res.json({ profile });
  } catch (error) {
    next(error);
  }
};

//* Follow/Unfollow Profile
const followToggler = async (req, res, next) => {
  try {
    const { loggedUser } = req;
    if (!loggedUser) throw new UnauthorizedError();

    const { username } = req.params;

    const profile = await User.findOne({ username })
      .select("-email -password")
      .lean();

    if (!profile) throw new NotFoundError("User profile");

    const session = await mongoose.startSession();
    try {
      await session.withTransaction(async () => {
        if (req.method === "POST") {
          const result = await Follower.updateOne(
            {
              "_id.userId": profile._id,
              "_id.followerId": loggedUser._id,
            },
            {
              $setOnInsert: {
                _id: { userId: profile._id, followerId: loggedUser._id },
              },
            },
            { upsert: true, session }
          );
          if (result.upsertedCount === 1) {
            await User.updateOne(
              { _id: profile._id },
              { $inc: { followersCount: 1 } },
              { session }
            );
          }
        } else if (req.method === "DELETE") {
          const result = await Follower.deleteOne(
            {
              "_id.userId": profile._id,
              "_id.followerId": loggedUser._id,
            },
            { session }
          );
          if (result.deletedCount === 1) {
            await User.updateOne(
              { _id: profile._id },
              { $inc: { followersCount: -1 } },
              { session }
            );
          }
        }
      });
    } finally {
      await session.endSession();
    }

    // re-fetch profile to reflect possible changes (lean)
    const refreshedProfile = await User.findById(profile._id)
      .select("-email -password")
      .lean();

    await appendFollowers(loggedUser, refreshedProfile);

    res.json({ profile: refreshedProfile });
  } catch (error) {
    next(error);
  }
};

module.exports = { getProfile, followToggler };
